<?php
declare(strict_types=1);
require dirname(__DIR__).'/php/domain.php';
$passed=0;$actor=['id'=>'member','name'=>'Hasindu','email'=>'test@example.test','userId'=>'test'];$clock='2026-10-26T04:00:00Z';
function eq(mixed $a,mixed $b,string $why=''):void{if($a!==$b)throw new RuntimeException($why.' Expected '.json_encode($b).', got '.json_encode($a));}
function rejects(callable $fn,string $contains):void{try{$fn();}catch(InputError $e){if(str_contains($e->getMessage(),$contains))return;throw $e;}throw new RuntimeException('Expected rejection: '.$contains);}
function fresh():array{global $actor;$b=rf_empty_board();$b['members']=[$actor];return $b;}
function act(array $b,string $action,array $p):array{global $actor,$clock;return rf_apply($b,$action,$p,$actor,$clock);}
function add(array $b,array $extra=[]):array{return act($b,'task.add',array_merge(['name'=>'Stock transfer','ownerId'=>'member','origin'=>'internal','category'=>'feature','projectId'=>'erf','environment'=>'dev','deadline'=>'2026-11-05'],$extra));}
function check_case(string $name,callable $fn):void{global $passed;try{$fn();$passed++;echo "PASS $name\n";}catch(Throwable $e){fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");exit(1);}}
check_case('default project and untouched start date',function(){$old=fresh();$b=add($old);eq(count($old['tasks']),0);eq($b['tasks'][0]['status'],'pending');eq($b['tasks'][0]['startedAt'],null);eq($b['tasks'][0]['addedAt'],'2026-10-26T04:00:00Z');});
check_case('multiple projects and environments remain distinct',function(){$b=act(fresh(),'project.add',['name'=>'Second product']);$project=$b['projects'][1]['id'];$b=add($b);$b=add($b,['projectId'=>$project,'environment'=>'live']);eq($b['tasks'][0]['projectId'],'erf');eq($b['tasks'][1]['projectId'],$project);eq($b['tasks'][1]['environment'],'live');rejects(fn()=>act($b,'project.add',['name'=>'second PRODUCT']),'already exists');});
check_case('all five workflow statuses retain their own history',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];foreach(['working','up_for_testing','testing','done'] as $status){$b=act($b,'task.status',['id'=>$id,'status'=>$status]);eq($b['tasks'][0]['status'],$status);}eq(count($b['tasks']),1);eq($b['tasks'][0]['startedAt'],'2026-10-26T04:00:00Z');rejects(fn()=>act($b,'task.status',['id'=>$id,'status'=>'working']),'reason');});
check_case('Done Dev issue creates Pending Live with independent state',function(){$b=add(fresh(),['category'=>'issue']);$id=$b['tasks'][0]['id'];$b=act($b,'task.done',['id'=>$id]);eq(count($b['tasks']),2);eq($b['tasks'][0]['status'],'done');eq($b['tasks'][1]['status'],'pending');eq($b['tasks'][1]['startedAt'],null);eq($b['tasks'][1]['environment'],'live');eq($b['tasks'][1]['sourceTaskId'],$id);eq($b['tasks'][0]['liveTaskId'],$b['tasks'][1]['id']);$live=$b['tasks'][1]['id'];$b=act($b,'task.status',['id'=>$live,'status'=>'testing']);eq($b['tasks'][0]['status'],'done');eq($b['tasks'][1]['status'],'testing');$b=act($b,'task.done',['id'=>$id]);eq(count($b['tasks']),2);eq($b['tasks'][1]['status'],'testing');});
check_case('a feature goes Live only through explicit selection',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];$b=act($b,'task.done',['id'=>$id]);eq(count($b['tasks']),1);$b=act($b,'task.promote',['id'=>$id]);eq(count($b['tasks']),2);$b=act($b,'task.promote',['id'=>$id]);eq(count($b['tasks']),2);eq($b['tasks'][1]['status'],'pending');});
check_case('a feature may be selected for Live before Dev completion',function(){$b=add(fresh());$b=act($b,'task.promote',['id'=>$b['tasks'][0]['id']]);eq($b['tasks'][0]['status'],'pending');eq($b['tasks'][1]['status'],'pending');});
check_case('unfinished issues cannot be manually sent; Live cannot promote',function(){$b=add(fresh(),['category'=>'issue']);rejects(fn()=>act($b,'task.promote',['id'=>$b['tasks'][0]['id']]),'when Done');$b=act($b,'task.done',['id'=>$b['tasks'][0]['id']]);rejects(fn()=>act($b,'task.promote',['id'=>$b['tasks'][1]['id']]),'Only Dev');});
check_case('subtasks inherit category, client and scope; their own completion promotes only that entry',function(){$b=add(fresh(),['category'=>'issue','origin'=>'client','client'=>'Green Mart']);$id=$b['tasks'][0]['id'];$b=add($b,['parentId'=>$id,'name'=>'Approval','deadline'=>null,'projectId'=>'invalid','category'=>null]);eq($b['tasks'][1]['category'],'issue');eq($b['tasks'][1]['client'],'Green Mart');eq($b['tasks'][1]['projectId'],'erf');rejects(fn()=>act($b,'task.done',['id'=>$id]),'subtasks');$b=act($b,'task.done',['id'=>$b['tasks'][1]['id']]);eq(count($b['tasks']),3);$b=act($b,'task.done',['id'=>$id]);eq(count($b['tasks']),4);eq($b['tasks'][2]['parentId'],$b['tasks'][3]['id']);eq($b['tasks'][2]['status'],'pending');});
check_case('pause is separate from testing status and deadline',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];$b=act($b,'task.status',['id'=>$id,'status'=>'testing']);$b=act($b,'task.pause',['id'=>$id,'reason'=>'Urgent work']);eq($b['tasks'][0]['status'],'testing');eq($b['tasks'][0]['paused'],true);eq($b['tasks'][0]['deadline'],'2026-11-05');rejects(fn()=>act($b,'task.done',['id'=>$id]),'Resume');$b=act($b,'task.resume',['id'=>$id]);eq($b['tasks'][0]['paused'],false);eq($b['tasks'][0]['status'],'testing');});
check_case('parent pauses active subtasks and leaves pending ones untouched',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];$b=add($b,['parentId'=>$id]);$b=add($b,['parentId'=>$id]);$b=act($b,'task.status',['id'=>$b['tasks'][1]['id'],'status'=>'up_for_testing']);$b=act($b,'task.pause',['id'=>$id,'reason'=>'Urgent receipt']);eq(array_column($b['tasks'],'paused'),[true,true,false]);$b=act($b,'task.resume',['id'=>$id,'resumeSubtasks'=>true]);eq(array_column($b['tasks'],'paused'),[false,false,false]);eq($b['tasks'][1]['status'],'up_for_testing');});
check_case('independent child pause is retained',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];$b=add($b,['parentId'=>$id]);$child=$b['tasks'][1]['id'];$b=act($b,'task.start',['id'=>$child]);$b=act($b,'task.pause',['id'=>$child,'reason'=>'Own blocker']);$b=act($b,'task.pause',['id'=>$id,'reason'=>'Other work']);$b=act($b,'task.resume',['id'=>$id,'resumeSubtasks'=>true]);eq($b['tasks'][1]['paused'],true);});
check_case('deadline changes preserve every commitment and enforce child bounds',function(){$b=add(fresh());$id=$b['tasks'][0]['id'];$b=act($b,'task.extend',['id'=>$id,'deadline'=>'2026-11-08','reason'=>'More work']);$b=act($b,'task.extend',['id'=>$id,'deadline'=>'2026-11-10','reason'=>'Testing']);$events=array_values(array_filter($b['tasks'][0]['history'],fn($h)=>$h['type']==='deadline_extended'));eq($events[0]['from'],'2026-11-05');eq($events[1]['from'],'2026-11-08');rejects(fn()=>add($b,['parentId'=>$id,'deadline'=>'2026-12-01']),'parent deadline');rejects(fn()=>act($b,'task.extend',['id'=>$id,'deadline'=>'2026-11-12','reason'=>'']),'reason');});
check_case('cross-environment blockers are rejected',function(){$b=add(fresh());$b=add($b,['environment'=>'live']);$id=$b['tasks'][0]['id'];$b=act($b,'task.start',['id'=>$id]);rejects(fn()=>act($b,'task.pause',['id'=>$id,'reason'=>'Wait','waitingFor'=>$b['tasks'][1]['id']]),'same project');});
check_case('future held meetings and invalid dates rejected',function(){$b=fresh();rejects(fn()=>act($b,'meeting.add',['title'=>'Planning','date'=>'2026-11-01','time'=>'10:00','status'=>'held','projectId'=>'erf','environment'=>'dev']),'future');rejects(fn()=>add($b,['deadline'=>'2026-02-30']),'valid date');$b=act($b,'meeting.add',['title'=>'Review','date'=>'2026-10-26','time'=>'10:00','status'=>'held','projectId'=>'erf','environment'=>'live']);eq($b['meetings'][0]['environment'],'live');eq($b['meetings'][0]['duration'],null);});
check_case('legacy records migrate into the default Dev project',function(){$b=add(fresh());unset($b['projects'],$b['schemaVersion']);unset($b['tasks'][0]['projectId'],$b['tasks'][0]['environment'],$b['tasks'][0]['category'],$b['tasks'][0]['paused']);$b['tasks'][0]['status']='paused';$b=rf_normalize($b);eq($b['tasks'][0]['status'],'working');eq($b['tasks'][0]['paused'],true);eq($b['tasks'][0]['environment'],'dev');});


check_case('independent issue subtask keeps Live progress when a feature parent is promoted later',function(){$b=add(fresh());$parent=$b['tasks'][0]['id'];$b=add($b,['parentId'=>$parent,'category'=>'issue']);$child=$b['tasks'][1]['id'];$b=act($b,'task.done',['id'=>$child]);eq(count($b['tasks']),3);eq($b['tasks'][2]['parentId'],null);$liveChild=$b['tasks'][2]['id'];$b=act($b,'task.status',['id'=>$liveChild,'status'=>'testing']);$b=act($b,'task.promote',['id'=>$parent]);eq(count($b['tasks']),4);eq($b['tasks'][2]['status'],'testing');eq($b['tasks'][2]['parentId'],$b['tasks'][3]['id']);eq($b['tasks'][0]['status'],'working');});

echo "$passed domain checks passed.\n";
